/* cppi::11298c32a72c5f5bb63596c8bd5d126a48925576ffbe25acabbd29b05e297bb6 */
SELECT COUNT(*) FROM (SELECT business_date, sum(market_value_reporting_currency) AS mv_rc, sum(period_result_node_by_node_reporting_currency) AS pnl_rc FROM performance.scd_performance_seclvl WHERE business_date BETWEEN '2024-04-01' AND '2025-03-31' AND aggregation_level_1 IN (SELECT model_portfolio FROM performance.scd_performance_invstr_flatten WHERE business_date = (SELECT max(business_date) FROM performance.scd_performance_invstr_flatten) AND investmentstructurelevel3 IN ('EPM', 'Macro Strategies', 'Quantitative Strategies & Risk Premia') AND investmentstructurelevel4 IN ('EPM Core', 'EPM Corporate Expenses', 'EPM Legacy', 'MS CMF Common', 'Legacy')) GROUP BY business_date
) dbvrcnt

/* cppi::11298c32a72c5f5bb63596c8bd5d126a48925576ffbe25acabbd29b05e297bb6 */
SELECT COUNT(*) FROM (SELECT business_date, sum(market_value_reporting_currency) AS mv_rc, sum(period_result_node_by_node_reporting_currency) AS pnl_rc FROM performance.scd_performance_seclvl WHERE business_date BETWEEN '2024-04-01' AND '2025-03-31' AND aggregation_level_1 IN (SELECT model_portfolio FROM performance.scd_performance_invstr_flatten WHERE business_date = (SELECT max(business_date) FROM performance.scd_performance_invstr_flatten) AND investmentstructurelevel3 IN ('EPM', 'Macro Strategies', 'Quantitative Strategies & Risk Premia') AND investmentstructurelevel4 IN ('EPM Core', 'EPM Corporate Expenses', 'EPM Legacy', 'MS CMF Common', 'Legacy')) GROUP BY business_date
) dbvrcnt

